# Investigação exploratória numérica; não produz gráficos finais.
# Executar após 01 e 02: Rscript scripts/03_investigacao_exploratoria.R
suppressPackageStartupMessages({ library(readr); library(dplyr); library(tidyr); library(ggplot2) })
source("R/config.R")
dir.create(diretorio_saida("outputs", "exploracao"), recursive = TRUE, showWarnings = FALSE)
ler_saida <- function(...) read_csv(diretorio_saida(...), show_col_types = FALSE)
fraudes <- ler_saida("outputs", "tabelas", "fraudes_mensal.csv")
transacoes <- ler_saida("outputs", "tabelas", "transacoes_mensal.csv")
# Comparação nacional: contestações não são tratadas como taxa de fraude.
painel <- fraudes %>% inner_join(transacoes, by = "AnoMes") %>% arrange(AnoMes) %>% mutate(indice_mes = row_number(), data = as.Date(paste0(AnoMes, "01"), format = "%Y%m%d"), valor_medio_transacao = valor_total / quantidade_total, across(c(QtdePixcontestados, Qtdecontestacoesaceitas, ValorPixcontestadosaceitos, valor_total, quantidade_total), list(variacao_pct = ~ 100 * (.x / lag(.x) - 1), indice_base100 = ~ 100 * .x / first(.x)), .names = "{.fn}_{.col}"), divergencia_crescimento_qtde = variacao_pct_QtdePixcontestados - variacao_pct_quantidade_total, divergencia_crescimento_valor = variacao_pct_ValorPixcontestadosaceitos - variacao_pct_valor_total)
write_csv(painel, diretorio_saida("outputs", "exploracao", "painel_nacional_indicadores.csv"))
correlacao <- function(x, y, nome_x, nome_y, metodo) { completos <- complete.cases(x, y); teste <- cor.test(x[completos], y[completos], method = metodo); tibble(variavel_fraude = nome_x, variavel_transacao = nome_y, metodo = metodo, n = sum(completos), correlacao = unname(teste$estimate), p_valor = teste$p.value) }
pares <- list(c("variacao_pct_QtdePixcontestados", "variacao_pct_quantidade_total"), c("variacao_pct_ValorPixcontestadosaceitos", "variacao_pct_valor_total"), c("variacao_pct_QtdePixcontestados", "variacao_pct_valor_total"))
correlacoes <- bind_rows(lapply(pares, function(p) bind_rows(correlacao(painel[[p[1]]], painel[[p[2]]], p[1], p[2], "pearson"), correlacao(painel[[p[1]]], painel[[p[2]]], p[1], p[2], "spearman"))))
write_csv(correlacoes, diretorio_saida("outputs", "exploracao", "correlacoes_variacoes_mensais.csv"))
variacoes_longo <- painel %>% select(AnoMes, starts_with("variacao_pct_"), starts_with("divergencia_")) %>% pivot_longer(-AnoMes, names_to = "indicador", values_to = "variacao_pct") %>% filter(!is.na(variacao_pct))
limites <- variacoes_longo %>% group_by(indicador) %>% summarise(q1 = quantile(variacao_pct, .25), q3 = quantile(variacao_pct, .75), .groups = "drop") %>% mutate(iiq = q3 - q1, limite_inferior = q1 - 1.5 * iiq, limite_superior = q3 + 1.5 * iiq)
atipicos <- variacoes_longo %>% inner_join(limites, by = "indicador") %>% filter(variacao_pct < limite_inferior | variacao_pct > limite_superior) %>% arrange(indicador, AnoMes)
write_csv(atipicos, diretorio_saida("outputs", "exploracao", "meses_atipicos_variacoes.csv"))
tendencias <- bind_rows(lapply(c("QtdePixcontestados", "quantidade_total", "ValorPixcontestadosaceitos", "valor_total"), function(v) { ajuste <- lm(log(painel[[v]]) ~ painel$indice_mes); tibble(variavel = v, crescimento_mensal_medio_pct = 100 * (exp(coef(ajuste)[2]) - 1), r2_ajuste_log = summary(ajuste)$r.squared) }))
write_csv(tendencias, diretorio_saida("outputs", "exploracao", "tendencias_log_lineares.csv"))
# Bases grandes: agregações em blocos, sem reter as linhas originais.
municipio_periodo <- tibble(); regiao_mensal <- tibble(); perfil_detalhado <- tibble()
callback_municipios <- DataFrameCallback$new(function(x, pos) { x <- x %>% filter(!is.na(Municipio_Ibge)) %>% mutate(valor_pagador = VL_PagadorPF + VL_PagadorPJ, quantidade_pagador = QT_PagadorPF + QT_PagadorPJ); municipio_periodo <<- bind_rows(municipio_periodo, x %>% group_by(Municipio_Ibge, Municipio, Estado, Regiao) %>% summarise(valor_pagador = sum(valor_pagador), quantidade_pagador = sum(quantidade_pagador), .groups = "drop")); regiao_mensal <<- bind_rows(regiao_mensal, x %>% group_by(AnoMes, Regiao) %>% summarise(valor_pagador = sum(valor_pagador), quantidade_pagador = sum(quantidade_pagador), .groups = "drop")); invisible() })
invisible(read_csv_chunked(arquivo_bruto("transacoes_pix_municipio.csv"), callback = callback_municipios, chunk_size = 50000, col_types = tipos_municipios, locale = locale_pix, na = na_pix, progress = FALSE))
municipio_periodo <- municipio_periodo %>% group_by(Municipio_Ibge, Municipio, Estado, Regiao) %>% summarise(across(c(valor_pagador, quantidade_pagador), sum), .groups = "drop") %>% arrange(desc(valor_pagador)) %>% mutate(participacao_valor_pct = 100 * valor_pagador / sum(valor_pagador), participacao_acumulada_pct = cumsum(participacao_valor_pct), ordem = row_number())
regiao_mensal <- regiao_mensal %>% group_by(AnoMes, Regiao) %>% summarise(across(c(valor_pagador, quantidade_pagador), sum), .groups = "drop")
concentracao <- municipio_periodo %>% summarise(municipios = n(), participacao_top10_pct = sum(participacao_valor_pct[ordem <= 10]), participacao_top100_pct = sum(participacao_valor_pct[ordem <= 100]), hhi_valor = sum((participacao_valor_pct / 100)^2))
q_log <- quantile(log1p(municipio_periodo$valor_pagador), c(.25, .75)); lim_sup_log <- q_log[2] + 1.5 * diff(q_log)
atipicos_municipais <- municipio_periodo %>% mutate(atipico_superior_log = log1p(valor_pagador) > lim_sup_log) %>% filter(atipico_superior_log)
write_csv(municipio_periodo, diretorio_saida("outputs", "exploracao", "municipios_periodo.csv")); write_csv(regiao_mensal, diretorio_saida("outputs", "exploracao", "regiao_mensal.csv")); write_csv(concentracao, diretorio_saida("outputs", "exploracao", "concentracao_municipal.csv")); write_csv(atipicos_municipais, diretorio_saida("outputs", "exploracao", "municipios_atipicos_log.csv"))
callback_detalhe <- DataFrameCallback$new(function(x, pos) { variaveis <- c("FORMAINICIACAO", "NATUREZA", "FINALIDADE", "PAG_PFPJ", "REC_PFPJ", "PAG_REGIAO", "REC_REGIAO"); perfil_detalhado <<- bind_rows(perfil_detalhado, bind_rows(lapply(variaveis, function(v) x %>% group_by(AnoMes, categoria = .data[[v]]) %>% summarise(valor_total = sum(VALOR), quantidade_total = sum(QUANTIDADE), .groups = "drop") %>% mutate(variavel = v)))); invisible() })
invisible(read_csv_chunked(arquivo_bruto("estatisticas_transacoes_pix.csv"), callback = callback_detalhe, chunk_size = 50000, col_types = tipos_transacoes, locale = locale_pix, na = na_pix, progress = FALSE))
perfil_detalhado <- perfil_detalhado %>% group_by(AnoMes, variavel, categoria) %>% summarise(across(c(valor_total, quantidade_total), sum), .groups = "drop")
write_csv(perfil_detalhado, diretorio_saida("outputs", "exploracao", "perfil_transacoes_mensal.csv"))
message("Investigação concluída: ", nrow(painel), " meses nacionais, ", nrow(municipio_periodo), " municípios e ", nrow(perfil_detalhado), " combinações mensais de perfil.")
